import{_ as e,o as t,c as o,a3 as s}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"ChildJob","description":"","frontmatter":{"title":"ChildJob"},"headers":[],"relativePath":"zh/00.docs/020.basic-features/060.tasks/020.ChildJob.md","filePath":"zh/00.docs/020.basic-features/060.tasks/020.ChildJob.md","lastUpdated":1784780539000}'),i={name:"zh/00.docs/020.basic-features/060.tasks/020.ChildJob.md"};function l(d,a,r,n,c,h){return t(),o("div",null,[...a[0]||(a[0]=[s('<h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h3><p>ChildJob基于node.js子进程实现。触发任务时才会创建进程，任务执行完毕后，必须调用进程退出的方法：Ps.exit()， 否则进程无法退出，造成资源浪费。</p><p>优点：随用随取，用完释放，不过多占用电脑资源。</p><p>不足：频繁、大量创建任务时，会有启动进程的开销，业务略微延迟，此类业务推荐使用ChildPoolJob。</p><blockquote><p>注意：node.js子进程中无法使用所有涉及electron的api（electron技术本身无法支持），相关业务请写在主进程</p></blockquote><h3 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./electron/jobs</span></span></code></pre></div><h3 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h3><p>请查看：<a href="/07.features/01.demo">demo分支中</a> 的示例代码</p>',9)])])}const _=e(i,[["render",l]]);export{b as __pageData,_ as default};
